      --negative: #ea3943;
      --shadow: 0 2px 10px rgba(15, 23, 42, 0.05);
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
      background: var(--bg);
      color: var(--text);
      min-width: 1180px;
    }
    .container { width: 96%; margin: 0 auto; }
    .top-metrics {
      background: #f8fafc;
      border-bottom: 1px solid var(--border);
      font-size: 12px;
      color: var(--muted);
    }
    .top-metrics .container {
      display: flex;
      gap: 18px;
      align-items: center;
      padding: 8px 0;
      flex-wrap: wrap;
    }
    .metric strong { color: var(--text); font-weight: 600; }
    .pos { color: var(--positive); font-weight: 600; }
    .neg { color: var(--negative); font-weight: 600; }

    header {
      background: var(--surface);
      border-bottom: 1px solid var(--border);
      box-shadow: var(--shadow);
      position: sticky;
      top: 0;
      z-index: 10;
    }
    .nav {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 14px 0;
      gap: 20px;
    }
    .brand { font-size: 20px; font-weight: 800; color: #0f172a; }
    .brand span { color: var(--brand); }
    .nav-links { display: flex; gap: 18px; }
    .nav-links a {
      text-decoration: none;
      color: #334155;
      font-size: 14px;
      font-weight: 600;
    }

    .promo {
      margin: 18px 0 10px;
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 12px;
      overflow: hidden;
      position: relative;
    }
    .promo-slide {
      display: none;
      padding: 16px 56px 16px 18px;
      font-size: 14px;
      line-height: 1.5;
    }
    .promo-slide.active { display: block; }
    .promo-slide strong { color: #0f172a; }
    .promo-controls {
      position: absolute;
      right: 10px;
      top: 50%;
      transform: translateY(-50%);
      display: flex;
      gap: 6px;
    }

    .ai-alert {
      background: linear-gradient(90deg, #dbeafe, #eff6ff);
      border: 1px solid #bfdbfe;
      padding: 10px 14px;
      border-radius: 10px;
      font-size: 13px;
      color: #1e3a8a;
      margin: 0 0 12px;
    }

    .tabs-row {
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;
      gap: 10px;
      margin: 8px 0;
    }
    .tabs { display: flex; gap: 8px; flex-wrap: wrap; }
    .tab {
      background: var(--surface);
      border: 1px solid var(--border);
      color: #334155;
      border-radius: 999px;
      padding: 7px 12px;
      font-size: 12px;
      font-weight: 600;
      cursor: pointer;
    }
    .tab.active {
      background: #eff6ff;
      border-color: #93c5fd;
      color: #1d4ed8;
    }

    .panel {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 12px;
      box-shadow: var(--shadow);
      overflow: hidden;
    }

    .table-toolbar {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 12px;
      border-bottom: 1px solid var(--border);
      gap: 8px;
      flex-wrap: wrap;
    }
    .btn {
      border: 1px solid var(--border);
      background: #fff;
      border-radius: 8px;
      padding: 7px 10px;
      font-size: 12px;
      font-weight: 600;
      color: #334155;
      cursor: pointer;
    }
    .btn.primary { border-color: #93c5fd; color: #1d4ed8; }
    .toggle-panel {
      display: none;
      padding: 10px 12px;
      border-bottom: 1px solid var(--border);
      background: #f8fafc;
      font-size: 12px;
    }
    .toggle-panel.active { display: block; }

    .table-wrap { overflow-x: auto; }
    table {
      width: 100%;
      border-collapse: collapse;
      font-size: 12px;
      background: var(--surface);
    }
    thead th {
      text-align: right;
      color: #475569;
      font-weight: 700;
      border-bottom: 1px solid var(--border);
      padding: 10px 8px;
      white-space: nowrap;
      background: #f8fafc;
    }
    th.left, td.left { text-align: left; }
    tbody td {
      border-bottom: 1px solid #f1f5f9;
      padding: 9px 8px;
      text-align: right;
      color: #0f172a;
      font-variant-numeric: tabular-nums;
      font-feature-settings: "tnum";
      white-space: nowrap;
    }
    tbody tr:hover { background: #f8fafc; }
    .coin-name { font-weight: 600; }
    .coin-sym { color: var(--muted); margin-left: 6px; font-weight: 500; }

    .sparkline {
      width: 120px;
      height: 34px;
      display: inline-block;
      border-radius: 4px;
      background: linear-gradient(180deg, rgba(37,99,235,0.05), rgba(37,99,235,0));
    }

    .pagination {
      display: flex;
      gap: 6px;
      justify-content: flex-end;
      align-items: center;
      padding: 12px;
      border-top: 1px solid var(--border);
      background: #fff;
    }
    .page-btn {
      min-width: 30px;
      height: 30px;
      border: 1px solid var(--border);
      background: #fff;
      border-radius: 6px;
      font-size: 12px;
      cursor: pointer;
    }
    .page-btn.active {
      background: #eff6ff;
      border-color: #93c5fd;
      color: #1d4ed8;
      font-weight: 700;
    }

    .summary, .info, footer {
      margin-top: 14px;
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 14px;
      box-shadow: var(--shadow);
    }
    .summary h3, .info h3 { margin: 0 0 8px; font-size: 16px; }
    .summary p, .info p { margin: 0; color: #334155; font-size: 13px; line-height: 1.6; }
    .read-more { margin-top: 8px; }
  </style>
</head>
<body>
  <div class="top-metrics">
    <div class="container" id="marketStatsBar"></div>
  </div>

  <header>
    <div class="container nav">
      <div class="brand">CoinTracker <span>Pro</span></div>
      <nav class="nav-links">
        <a href="index.html">Cryptocurrencies</a>
        <a href="index.html">Dashboards</a>
        <a href="index.html">Exchanges</a>
        <a href="index.html">DexScan</a>
      </nav>
    </div>
  </header>

  <main class="container">
    <section class="promo" aria-label="Promotional Banner">
      <div class="promo-slide active"><strong>Market Insight:</strong> BTC dominance rises to 59.04% as large caps outperform mid-cap altcoins this week.</div>
      <div class="promo-slide"><strong>New Listing Radar:</strong> Track newly added assets in real-time with advanced volatility and volume alerts.</div>
      <div class="promo-slide"><strong>Professional Signals:</strong> AI-generated momentum and liquidity signals now available for top 500 assets.</div>
      <div class="promo-controls">
        <button class="btn" id="promoPrev">◀</button>
        <button class="btn" id="promoNext">▶</button>
      </div>
    </section>

    <section class="ai-alert" id="aiAlertsBar">AI Alerts: 12 assets triggered unusual volume spikes in the last hour. Review top anomalies before session close.</section>

    <div class="tabs-row">
      <div class="tabs" id="categoryTabs"></div>
      <div class="tabs" id="networkTabs"></div>
    </div>

    <section class="panel">
      <div class="table-toolbar">
        <div><strong>Cryptocurrency Rankings</strong> <span style="color:#64748b;font-size:12px;">(Top 100 per page)</span></div>
        <div style="display:flex; gap:8px;">
          <button class="btn" id="columnsToggle">Columns</button>
          <button class="btn" id="filtersToggle">Filters</button>
        </div>
      </div>

      <div class="toggle-panel" id="columnsPanel"></div>
      <div class="toggle-panel" id="filtersPanel"></div>

      <div class="table-wrap">
        <table id="cryptoTable">
          <thead>
            <tr>
              <th class="left">#</th>
              <th class="left">Name</th>
              <th>Price</th>
              <th>1h %</th>
              <th>24h %</th>
              <th>7d %</th>
              <th>Market Cap</th>
              <th>Volume (24h)</th>
              <th>Circulating Supply</th>
              <th class="left">Last 7 Days</th>
            </tr>
          </thead>
          <tbody></tbody>
        </table>
      </div>

      <div class="pagination" id="pagination"></div>
    </section>

    <section class="summary">
      <h3>Market Summary</h3>
      <p id="summaryText"></p>
      <div class="read-more"><button class="btn primary" id="readMoreBtn">Read More</button></div>
    </section>

    <section class="info">
      <h3>About CoinTracker Pro</h3>
      <p>CoinTracker Pro provides professional-grade cryptocurrency market intelligence, combining live prices, liquidity metrics, and multi-timeframe performance to support data-driven trading and investment decisions.</p>
    </section>

    <footer>
      <p style="margin:0;color:#64748b;font-size:12px;">© 2026 CoinTracker Pro. Data shown for benchmarking and demonstration purposes.</p>
    </footer>
  </main>

  <script>
    const marketStats = [
      { label: 'Market Cap', value: '$2.56T', change: '1.46%', positive: true },
      { label: 'CMC20', value: '57', change: 'Neutral', positive: null },
      { label: 'Fear & Greed', value: '37/100', change: 'Neutral', positive: null },
      { label: 'Altcoin Season', value: '37/100', change: 'Low', positive: null }
    ];

    const categories = ['Top', 'Trending', 'Watchlist', 'Prediction Markets', 'Most Visited', 'New'];
    const networks = ['All Networks', 'BSC', 'Solana', 'Base', 'Ethereum', 'More'];

    const coins = [];
    const baseCoins = [
      ['Bitcoin', 'BTC', 75612.78, 0.11, 1.47, 3.25, 1.51e12, 28.435e10, 20.01e6],
      ['Ethereum', 'ETH', 2356.00, -0.24, 0.81, 2.91, 2.84e11, 14.87e9, 120.35e6],
      ['Tether', 'USDT', 1.00, 0.01, 0.02, 0.01, 9.82e10, 52.45e9, 98.20e9],
      ['BNB', 'BNB', 612.44, 0.32, 2.12, 5.48, 8.91e10, 2.21e9, 145.88e6],
      ['Solana', 'SOL', 176.22, -0.15, 3.52, 8.73, 7.64e10, 5.98e9, 433.71e6],
      ['USDC', 'USDC', 1.00, 0.00, -0.01, 0.01, 3.26e10, 8.54e9, 32.60e9],
      ['XRP', 'XRP', 0.62, 0.42, -1.14, 4.21, 3.44e10, 1.95e9, 55.40e9],
      ['Dogecoin', 'DOGE', 0.153, 0.28, 2.64, 6.11, 2.20e10, 1.24e9, 143.2e9],
      ['Toncoin', 'TON', 5.98, -0.33, 1.02, 3.15, 2.05e10, 6.91e8, 3.43e9],
      ['Cardano', 'ADA', 0.54, 0.19, -0.22, 2.79, 1.92e10, 8.75e8, 35.3e9],
      ['Litecoin', 'LTC', 88.25, 0.10, 1.33, 3.88, 6.58e9, 5.22e8, 74.6e6],
      ['Avalanche', 'AVAX', 37.40, -0.06, 2.45, 7.11, 1.43e10, 7.43e8, 382.4e6]
    ];

    for (let i = 1; i <= 8400; i++) {
      const b = baseCoins[(i - 1) % baseCoins.length];
      const drift = 1 - (i * 0.00011);
      const price = Math.max(0.0001, b[2] * drift);
      const oneH = b[3] + ((i % 9) - 4) * 0.03;
      const oneD = b[4] + ((i % 13) - 6) * 0.18;
      const sevenD = b[5] + ((i % 15) - 7) * 0.27;
      const cap = Math.max(1e7, b[6] * drift);
      const vol = Math.max(1e6, b[7] * (0.8 + (i % 10) * 0.04));
      const supply = Math.max(1, b[8] * (0.95 + (i % 7) * 0.01));
      const network = networks[(i % (networks.length - 1)) + 1] || 'Ethereum';
      const category = categories[i % categories.length];
      coins.push({ rank: i, name: b[0] + (i > 12 ? ' ' + i : ''), symbol: b[1], price, oneH, oneD, sevenD, cap, vol, supply, network, category });
    }

    const state = { category: 'Top', network: 'All Networks', page: 1, promo: 0, summaryExpanded: false };

    const formatMoney = (v) => {
      if (v >= 1e12) return '$' + (v / 1e12).toFixed(2) + 'T';
      if (v >= 1e9) return '$' + (v / 1e9).toFixed(2) + 'B';
      if (v >= 1e6) return '$' + (v / 1e6).toFixed(2) + 'M';
      if (v >= 1) return '$' + v.toLocaleString(undefined, { maximumFractionDigits: 2 });
      return '$' + v.toFixed(4);
    };
    const formatPct = (v) => `${v > 0 ? '+' : ''}${v.toFixed(2)}%`;

    function renderStatsBar() {
      const node = document.getElementById('marketStatsBar');
      node.innerHTML = marketStats.map(item => {
        const c = item.positive === true ? 'pos' : item.positive === false ? 'neg' : '';
        return `<span class="metric">${item.label}: <strong>${item.value}</strong> <span class="${c}">${item.change}</span></span>`;
      }).join('');
    }

    function renderTabs() {
      document.getElementById('categoryTabs').innerHTML = categories.map(c => `<button class="tab ${state.category===c?'active':''}" data-cat="${c}">${c}</button>`).join('');
      document.getElementById('networkTabs').innerHTML = networks.map(n => `<button class="tab ${state.network===n?'active':''}" data-net="${n}">${n}</button>`).join('');
    }

    function filteredCoins() {
      return coins.filter(c => (state.category === 'Top' || c.category === state.category) && (state.network === 'All Networks' || c.network === state.network));
    }

    function sparkline(value) {
      const up = value >= 0;
      const stroke = up ? '#16c784' : '#ea3943';
      return `<svg class="sparkline" viewBox="0 0 120 34" xmlns="http://www.w3.org/2000/svg"><polyline fill="none" stroke="${stroke}" stroke-width="2" points="0,22 12,21 24,19 36,20 48,18 60,17 72,15 84,13 96,12 108,10 120,${up?8:24}"/></svg>`;
    }

    function renderTable() {
      const rows = filteredCoins();
      const start = (state.page - 1) * 100;
      const current = rows.slice(start, start + 100);
      const tbody = document.querySelector('#cryptoTable tbody');
      tbody.innerHTML = current.map(c => `
        <tr>
          <td class="left">${c.rank}</td>
          <td class="left"><span class="coin-name">${c.name}</span><span class="coin-sym">${c.symbol}</span></td>
          <td>${formatMoney(c.price)}</td>
          <td class="${c.oneH >= 0 ? 'pos' : 'neg'}">${formatPct(c.oneH)}</td>
          <td class="${c.oneD >= 0 ? 'pos' : 'neg'}">${formatPct(c.oneD)}</td>
          <td class="${c.sevenD >= 0 ? 'pos' : 'neg'}">${formatPct(c.sevenD)}</td>
          <td>${formatMoney(c.cap)}</td>
          <td>${formatMoney(c.vol)}</td>
          <td>${(c.supply >= 1e9 ? (c.supply/1e9).toFixed(2)+'B' : c.supply >=1e6 ? (c.supply/1e6).toFixed(2)+'M' : c.supply.toFixed(2))} ${c.symbol}</td>
          <td class="left">${sparkline(c.sevenD)}</td>
        </tr>
      `).join('');

      const totalPages = Math.max(1, Math.ceil(rows.length / 100));
      if (state.page > totalPages) state.page = 1;
      const shown = [1,2,3,4,totalPages].filter((v,i,a)=>v>=1&&v<=totalPages&&a.indexOf(v)===i);
      document.getElementById('pagination').innerHTML = shown.map(p => `<button class="page-btn ${state.page===p?'active':''}" data-page="${p}">${p}</button>`).join('') + `<span style="font-size:12px;color:#64748b;margin-left:8px;">… ${totalPages}</span>`;
    }

    function renderSummary() {
      const base = 'The global cryptocurrency market cap today is $2.56T, a 1.47% change over the last 24 hours. Total crypto market volume over the last 24 hours is $156.9B. DeFi volume is currently 14.51% of total market volume, while stablecoin transactions account for 59.04% of the 24-hour volume profile.';
      const extra = ' Bitcoin remains the anchor asset for institutional positioning, while rotation into high-beta altcoins is visible in select sectors including AI, DePIN, and modular infrastructure. Liquidity remains concentrated in top-tier exchanges and deep USDT pairs.';
      document.getElementById('summaryText').textContent = state.summaryExpanded ? base + extra : base;
      document.getElementById('readMoreBtn').textContent = state.summaryExpanded ? 'Read Less' : 'Read More';
    }

    function renderPromo() {
      document.querySelectorAll('.promo-slide').forEach((el, i) => el.classList.toggle('active', i === state.promo));
    }

    document.addEventListener('click', (e) => {
      const cat = e.target.getAttribute('data-cat');
      if (cat) { state.category = cat; state.page = 1; renderTabs(); renderTable(); }
      const net = e.target.getAttribute('data-net');
      if (net) { state.network = net; state.page = 1; renderTabs(); renderTable(); }
      const page = e.target.getAttribute('data-page');
      if (page) { state.page = Number(page); renderTable(); }
    });

    document.getElementById('columnsToggle').addEventListener('click', () => {
      const p = document.getElementById('columnsPanel');
      p.classList.toggle('active');
      p.innerHTML = '<strong>Visible Columns:</strong> Rank, Name, Price, 1h%, 24h%, 7d%, Market Cap, Volume (24h), Circulating Supply, Last 7 Days';
    });

    document.getElementById('filtersToggle').addEventListener('click', () => {
      const p = document.getElementById('filtersPanel');
      p.classList.toggle('active');
      p.innerHTML = `<strong>Active Filters:</strong> Category = ${state.category}, Network = ${state.network}`;
    });

    document.getElementById('readMoreBtn').addEventListener('click', () => { state.summaryExpanded = !state.summaryExpanded; renderSummary(); });
    document.getElementById('promoPrev').addEventListener('click', () => { state.promo = (state.promo + 2) % 3; renderPromo(); });
    document.getElementById('promoNext').addEventListener('click', () => { state.promo = (state.promo + 1) % 3; renderPromo(); });
    setInterval(() => { state.promo = (state.promo + 1) % 3; renderPromo(); }, 5000);

    renderStatsBar();
    renderTabs();
    renderTable();
    renderSummary();
  </script>
</body>
</html>
EOF
